186	    /**
187	     * Find an available location for an object to be created in the simulation field.
188	     * The simulation is chosen at random and is changed if the randomly selected cell
189	     * already contains an object.
190	     *
191	     * @param field (Field) The simulation's field.
192	     * @return (Location) the available location found.
193	     */
194	    private Location findAvailableLocation(Field field)
195	    {
196	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
197	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
198	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
199	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
200	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
201	        }
202	        return new Location(randomDepth, randomWidth);
203	    }
